WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY city, region ORDER BY sqft DESC NULLS FIRST, id) AS rank_in_group FROM stores QUALIFY rank_in_group = 1) SELECT id, city, opened_date, sqft, CASE WHEN city RLIKE '^(Bangkok|Singapore)$' THEN 'OTHER_ZONE' WHEN city RLIKE '^(Chiang Mai|New York)$' THEN 'GROUP_B' ELSE 'CORE' END AS city_zone FROM deduped ORDER BY sqft NULLS LAST, city DESC
